  const groups = [];
  let current = '';
  let depth = 0;

  for (const char of paren_string) {
    if (char === ' ') continue;

    current += char;

    if (char === '(') {
      depth++;
    } else if (char === ')') {
      depth--;

      if (depth === 0) {
        groups.push(current);
        current = '';
      }
    }
  }

  return groups;
};

